mapper.select:
SELECT id, user_id, body, edited_at, created_at, updated_at
FROM posts
WHERE id = #{id}

SELECT 
FROM posts p
JOIN users u ON u.id = p.user_id
WHERE (p.user_id = #{viewerId}
       OR p.user_id IN (SELECT f.followee_id FROM follows f WHERE f.follower_id = #{viewerId}))

  AND p.id < #{before}

ORDER BY p.id DESC
LIMIT #{limit}

SELECT 
FROM posts p
JOIN users u ON u.id = p.user_id
WHERE p.user_id = #{userId}

  AND p.id < #{before}

ORDER BY p.id DESC
LIMIT #{limit}

SELECT EXISTS (
    SELECT 1
    FROM posts p
    WHERE (p.user_id = #{viewerId}
           OR p.user_id IN (SELECT f.followee_id FROM follows f WHERE f.follower_id = #{viewerId}))
      AND p.id > #{after}
)
